promptCalendar(aMethod, aItipItem, aWindow) {
  let needsCalendar = false;
  let targetCalendar = null;
  switch (aMethod) {
    // methods that don't require the calendar chooser:
    case "REFRESH":
    case "REQUEST:UPDATE":
    case "REQUEST:UPDATE-MINOR":
    case "PUBLISH:UPDATE":
    case "REPLY":
    case "CANCEL":
    case "COUNTER":
    case "DECLINECOUNTER":
      needsCalendar = false;
      break;
    default:
      needsCalendar = true;
      break;
  }

  if (needsCalendar) {
    let calendars = lazy.cal.manager
      .getCalendars()
      .filter(
        calendar =>
          itip.isSchedulingCalendar(calendar) && lazy.cal.acl.userCanAddItemsToCalendar(calendar)
      );

    if (aItipItem.receivedMethod == "REQUEST") {
      // try to further limit down the list to those calendars that
      // are configured to a matching attendee;
      const item = aItipItem.getItemList()[0];
      const matchingCals = calendars.filter(
        calendar => itip.getInvitedAttendee(item, calendar) != null
      );
      // if there's none, we will show the whole list of calendars:
      if (matchingCals.length > 0) {
        calendars = matchingCals;
      }
    }

    if (calendars.length == 0) {
      const msg = lazy.l10n.formatValueSync("imip-no-calendar-available");
      aWindow.alert(msg);
    } else if (calendars.length == 1) {
      // There's only one calendar, so it's silly to ask what calendar
      // the user wants to import into.
      targetCalendar = calendars[0];
    } else {
      // Preselect the calendar that already holds the item, otherwise the
      // current default calendar.
      let preselectId = null;
      const found = aItipItem.targetCalendar;
      if (found && found.type != "composite") {
        preselectId = found.id;
      } else {
        const defaultCalendar = calendars.find(calendar =>
          calendar.getProperty("calendar-main-default")
        );
        preselectId = defaultCalendar ? defaultCalendar.id : null;
      }

      // Ask what calendar to import into
      const args = {};
      args.calendars = calendars;
      args.preselectId = preselectId;
      args.onOk = aCal => {
        targetCalendar = aCal;
      };
      args.promptText = lazy.l10n.formatValueSync("import-prompt");
      aWindow.openDialog(
        "chrome://calendar/content/chooseCalendarDialog.xhtml",
        "_blank",
        "chrome,titlebar,modal,resizable",
        args
      );
    }

    if (targetCalendar) {
      aItipItem.targetCalendar = targetCalendar;
    }
  }

  return !needsCalendar || targetCalendar != null;
